import{_ as d,o as e,c as o,ak as r}from"./chunks/framework.B-zz2iUS.js";const b=JSON.parse('{"title":"API 概览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/api/API-overview.md","filePath":"zh/api/API-overview.md","lastUpdated":1783744111000}'),a={name:"zh/api/API-overview.md"};function c(i,t,h,n,s,l){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="api-概览" tabindex="-1">API 概览 <a class="header-anchor" href="#api-概览" aria-label="Permalink to “API 概览”">​</a></h1><p>SenRi FFI 是一个<strong>跨语言 FFI（外部函数接口）统一抽象库</strong>，提供 JavaScript/TypeScript 和 Python 两个语言版本，共享统一的类型系统和 API 设计理念。</p><h2 id="语言-运行时版本" tabindex="-1">语言/运行时版本 <a class="header-anchor" href="#语言-运行时版本" aria-label="Permalink to “语言/运行时版本”">​</a></h2><table tabindex="0"><thead><tr><th>语言/运行时</th><th>包</th><th>版本</th><th>文档</th></tr></thead><tbody><tr><td>JavaScript/TypeScript（KossJS、Node.js、Bun、Deno）</td><td><code>@tt23xrstudio/senri_ffi</code></td><td>0.3.2</td><td><a href="/SenRiFFI/zh/js/api/API-overview-js.html">JS API 文档</a></td></tr><tr><td>Python（ctypes / cffi）</td><td><code>senri-ffi</code></td><td>0.1.0</td><td><a href="/SenRiFFI/zh/py/api/API-overview-py.html">Python API 文档</a></td></tr></tbody></table><h2 id="统一-api-设计" tabindex="-1">统一 API 设计 <a class="header-anchor" href="#统一-api-设计" aria-label="Permalink to “统一 API 设计”">​</a></h2><p>两个语言版本共享相同的设计理念和 API 命名：</p><h3 id="library-—-库加载与函数绑定" tabindex="-1">Library — 库加载与函数绑定 <a class="header-anchor" href="#library-—-库加载与函数绑定" aria-label="Permalink to “Library — 库加载与函数绑定”">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>JavaScript/TypeScript</th><th>Python</th></tr></thead><tbody><tr><td>加载库</td><td><code>Library.load(path)</code></td><td><code>Library.load(path)</code></td></tr><tr><td>绑定函数</td><td><code>lib.func(name, ret, args)</code></td><td><code>lib.func(name, ret, args)</code></td></tr><tr><td>异步绑定</td><td><code>lib.funcAsync(name, ret, args)</code></td><td>❌ 不支持</td></tr><tr><td>关闭库</td><td><code>lib.close()</code> / <code>lib.closeAsync()</code></td><td><code>lib.close()</code></td></tr></tbody></table><h3 id="types-—-统一类型系统" tabindex="-1">types — 统一类型系统 <a class="header-anchor" href="#types-—-统一类型系统" aria-label="Permalink to “types — 统一类型系统”">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>C 等价</th><th>JS 对应</th><th>Python 对应</th></tr></thead><tbody><tr><td><code>types.void</code></td><td><code>void</code></td><td><code>undefined</code></td><td><code>None</code></td></tr><tr><td><code>types.int8</code></td><td><code>int8_t</code></td><td><code>number</code></td><td><code>int</code></td></tr><tr><td><code>types.uint8</code></td><td><code>uint8_t</code></td><td><code>number</code></td><td><code>int</code></td></tr><tr><td><code>types.int16</code></td><td><code>int16_t</code></td><td><code>number</code></td><td><code>int</code></td></tr><tr><td><code>types.uint16</code></td><td><code>uint16_t</code></td><td><code>number</code></td><td><code>int</code></td></tr><tr><td><code>types.int32</code></td><td><code>int32_t</code></td><td><code>number</code></td><td><code>int</code></td></tr><tr><td><code>types.uint32</code></td><td><code>uint32_t</code></td><td><code>number</code></td><td><code>int</code></td></tr><tr><td><code>types.int64</code></td><td><code>int64_t</code></td><td><code>bigint</code></td><td><code>int</code></td></tr><tr><td><code>types.uint64</code></td><td><code>uint64_t</code></td><td><code>bigint</code></td><td><code>int</code></td></tr><tr><td><code>types.float32</code></td><td><code>float</code></td><td><code>number</code></td><td><code>float</code></td></tr><tr><td><code>types.float64</code></td><td><code>double</code></td><td><code>number</code></td><td><code>float</code></td></tr><tr><td><code>types.pointer</code></td><td><code>void*</code></td><td><code>bigint</code></td><td><code>int</code></td></tr><tr><td><code>types.cstring</code></td><td><code>char*</code></td><td><code>string</code></td><td><code>bytes</code></td></tr></tbody></table><h3 id="类型构造器" tabindex="-1">类型构造器 <a class="header-anchor" href="#类型构造器" aria-label="Permalink to “类型构造器”">​</a></h3><table tabindex="0"><thead><tr><th>构造器</th><th>JavaScript/TypeScript</th><th>Python</th></tr></thead><tbody><tr><td>指针类型</td><td><code>pointer(types.int32)</code></td><td><code>pointer(types.int32)</code></td></tr><tr><td>数组类型</td><td><code>array(types.uint8, 256)</code></td><td><code>array(types.uint8, 256)</code></td></tr></tbody></table><h3 id="struct-—-结构体" tabindex="-1">struct — 结构体 <a class="header-anchor" href="#struct-—-结构体" aria-label="Permalink to “struct — 结构体”">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>JavaScript/TypeScript</th><th>Python</th></tr></thead><tbody><tr><td>定义</td><td><code>struct({ x: types.float64 })</code></td><td><code>struct({&quot;x&quot;: types.float64})</code></td></tr><tr><td>创建</td><td><code>new Point({ x: 1.0 })</code></td><td><code>Point({&quot;x&quot;: 1.0})</code></td></tr><tr><td>大小</td><td><code>Point.sizeof</code></td><td><code>Point._total_size</code></td></tr><tr><td>指针</td><td><code>p.ptr</code> / <code>p.toPointer()</code></td><td><code>p.ptr</code> / <code>p.to_pointer()</code></td></tr><tr><td>反序列化</td><td><code>Point.fromPointer(ptr)</code></td><td><code>Point.from_pointer(ptr)</code></td></tr></tbody></table><h3 id="pointer-—-指针读写" tabindex="-1">Pointer — 指针读写 <a class="header-anchor" href="#pointer-—-指针读写" aria-label="Permalink to “Pointer — 指针读写”">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>JavaScript/TypeScript</th><th>Python</th></tr></thead><tbody><tr><td>读 int32</td><td><code>ptr.readInt32(offset)</code></td><td><code>ptr.read_int32(offset)</code></td></tr><tr><td>写 int32</td><td><code>ptr.writeInt32(offset, v)</code></td><td><code>ptr.write_int32(offset, v)</code></td></tr><tr><td>读 float64</td><td><code>ptr.readFloat64(offset)</code></td><td><code>ptr.read_float64(offset)</code></td></tr><tr><td>写 float64</td><td><code>ptr.writeFloat64(offset, v)</code></td><td><code>ptr.write_float64(offset, v)</code></td></tr><tr><td>读指针</td><td><code>ptr.readPointer(offset)</code></td><td><code>ptr.read_pointer(offset)</code></td></tr><tr><td>写指针</td><td><code>ptr.writePointer(offset, v)</code></td><td><code>ptr.write_pointer(offset, v)</code></td></tr><tr><td>读字符串</td><td><code>ptr.readCString(offset)</code></td><td><code>ptr.read_cstring(offset)</code></td></tr><tr><td>写字符串</td><td><code>ptr.writeCString(offset, s)</code></td><td><code>ptr.write_cstring(offset, s)</code></td></tr><tr><td>偏移</td><td><code>ptr.add(offset)</code></td><td><code>ptr.add(offset)</code></td></tr><tr><td>地址</td><td><code>ptr.address</code> (bigint)</td><td><code>ptr.address</code> (int)</td></tr><tr><td>空检查</td><td><code>ptr.isNull()</code></td><td><code>ptr.is_null()</code></td></tr></tbody></table><h3 id="callback-—-回调函数" tabindex="-1">callback — 回调函数 <a class="header-anchor" href="#callback-—-回调函数" aria-label="Permalink to “callback — 回调函数”">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>JavaScript/TypeScript</th><th>Python</th></tr></thead><tbody><tr><td>创建</td><td><code>callback(ret, args, fn)</code></td><td><code>callback(ret, args, fn)</code></td></tr><tr><td>获取地址</td><td><code>cb.address</code></td><td><code>cb.address</code></td></tr><tr><td>自动释放</td><td><code>FinalizationRegistry</code></td><td><code>weakref.WeakValueDictionary</code></td></tr></tbody></table><h3 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to “内存管理”">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>JavaScript/TypeScript</th><th>Python</th></tr></thead><tbody><tr><td>分配</td><td><code>alloc(size)</code></td><td><code>alloc(size)</code></td></tr><tr><td>释放</td><td><code>free(ptr)</code></td><td><code>free(ptr)</code></td></tr><tr><td>获取地址</td><td><code>addressOf(buffer)</code></td><td><code>address_of(buffer)</code></td></tr><tr><td>错误码</td><td><code>errno()</code></td><td><code>errno()</code></td></tr><tr><td>错误描述</td><td><code>strerror(code)</code></td><td><code>strerror(code)</code></td></tr></tbody></table><h3 id="错误类型" tabindex="-1">错误类型 <a class="header-anchor" href="#错误类型" aria-label="Permalink to “错误类型”">​</a></h3><table tabindex="0"><thead><tr><th>错误类</th><th>说明</th></tr></thead><tbody><tr><td><code>FFIError</code></td><td>通用 FFI 错误</td></tr><tr><td><code>FFITypeError</code></td><td>类型相关错误</td></tr><tr><td><code>FFIBackendError</code></td><td>自定义后端相关错误</td></tr></tbody></table><h3 id="自定义后端" tabindex="-1">自定义后端 <a class="header-anchor" href="#自定义后端" aria-label="Permalink to “自定义后端”">​</a></h3><p>两个语言版本均支持自定义 FFI 后端：</p><table tabindex="0"><thead><tr><th>API</th><th>JavaScript/TypeScript</th><th>Python</th></tr></thead><tbody><tr><td>接口</td><td><code>LibraryLike</code></td><td><code>LibraryLike</code>（鸭子类型）</td></tr><tr><td>检查</td><td><code>isLibraryLike(obj)</code></td><td><code>is_library_like(obj)</code></td></tr><tr><td>缺失方法</td><td><code>getMissingMethods(obj)</code></td><td><code>get_missing_methods(obj)</code></td></tr></tbody></table><hr><h2 id="快速导航" tabindex="-1">快速导航 <a class="header-anchor" href="#快速导航" aria-label="Permalink to “快速导航”">​</a></h2><h3 id="javascript-typescript" tabindex="-1">JavaScript/TypeScript <a class="header-anchor" href="#javascript-typescript" aria-label="Permalink to “JavaScript/TypeScript”">​</a></h3><ul><li><a href="/SenRiFFI/zh/js/guide/what-is-senri-ffi-js.html">什么是 SenRi FFI (JS)</a> — 项目背景和架构</li><li><a href="/SenRiFFI/zh/js/guide/getting-started-js.html">快速开始 (JS)</a> — 安装和第一个调用</li><li><a href="/SenRiFFI/zh/js/api/API-overview-js.html">API 文档 (JS)</a> — 完整 JS API 参考</li></ul><h3 id="python" tabindex="-1">Python <a class="header-anchor" href="#python" aria-label="Permalink to “Python”">​</a></h3><ul><li><a href="/SenRiFFI/zh/py/guide/what-is-senri-ffi-py.html">什么是 SenRi FFI (Python)</a> — 项目背景和架构</li><li><a href="/SenRiFFI/zh/py/guide/getting-started-py.html">快速开始 (Python)</a> — 安装和第一个调用</li><li><a href="/SenRiFFI/zh/py/api/API-overview-py.html">API 文档 (Python)</a> — 完整 Python API 参考</li></ul>',31)])])}const f=d(a,[["render",c]]);export{b as __pageData,f as default};
